use split_decls_genesis :: ourprelude :: * ; use rustc_data_structures :: fx :: { FxHashMap , FxHashSet , FxIndexSet } ; use rustc_middle :: ty :: RegionVid ; use rustc_mir_dataflow :: points :: PointIndex ; use super :: { LiveLoans , LocalizedOutlivesConstraintSet } ; use crate :: BorrowSet ; use crate :: constraints :: OutlivesConstraint ; use crate :: region_infer :: values :: LivenessValues ; use crate :: type_check :: Locations ; #[doc = " Compute loan reachability to approximately trace loan liveness throughout the CFG, by"] #[doc = " traversing the full graph of constraints that combines:"] #[doc = " - the localized constraints (the physical edges),"] #[doc = " - with the constraints that hold at all points (the logical edges)."] pub (super) fn compute_loan_liveness < 'tcx > (liveness : & LivenessValues , outlives_constraints : impl Iterator < Item = OutlivesConstraint < 'tcx > > , borrow_set : & BorrowSet < 'tcx > , localized_outlives_constraints : & LocalizedOutlivesConstraintSet ,) -> LiveLoans { let mut live_loans = LiveLoans :: new (borrow_set . len ()) ; let logical_constraints = outlives_constraints . filter (| c | matches ! (c . locations , Locations :: All (_))) ; let graph = LocalizedConstraintGraph :: new (& localized_outlives_constraints , logical_constraints) ; let mut visited = FxHashSet :: default () ; let mut stack = Vec :: new () ; for (loan_idx , loan) in borrow_set . iter_enumerated () { visited . clear () ; stack . clear () ; let start_node = LocalizedNode { region : loan . region , point : liveness . point_from_location (loan . reserve_location) , } ; stack . push (start_node) ; while let Some (node) = stack . pop () { if ! visited . insert (node) { continue ; } if liveness . is_live_at (node . region , liveness . location_from_point (node . point)) { live_loans . insert (node . point , loan_idx) ; } for succ in graph . outgoing_edges (node) { stack . push (succ) ; } } } live_loans } #[doc = " The localized constraint graph indexes the physical and logical edges to compute a given node's"] #[doc = " successors during traversal."] struct LocalizedConstraintGraph { #[doc = " The actual, physical, edges we have recorded for a given node."] edges : FxHashMap < LocalizedNode , FxIndexSet < LocalizedNode > > , #[doc = " The logical edges representing the outlives constraints that hold at all points in the CFG,"] #[doc = " which we don't localize to avoid creating a lot of unnecessary edges in the graph. Some CFGs"] #[doc = " can be big, and we don't need to create such a physical edge for every point in the CFG."] logical_edges : FxHashMap < RegionVid , FxIndexSet < RegionVid > > , } #[doc = " A node in the graph to be traversed, one of the two vertices of a localized outlives constraint."] #[derive (Copy , Clone , PartialEq , Eq , Hash , Debug)] struct LocalizedNode { region : RegionVid , point : PointIndex , } impl LocalizedConstraintGraph { #[doc = " Traverses the constraints and returns the indexed graph of edges per node."] fn new < 'tcx > (constraints : & LocalizedOutlivesConstraintSet , logical_constraints : impl Iterator < Item = OutlivesConstraint < 'tcx > > ,) -> Self { let mut edges : FxHashMap < _ , FxIndexSet < _ > > = FxHashMap :: default () ; for constraint in & constraints . outlives { let source = LocalizedNode { region : constraint . source , point : constraint . from } ; let target = LocalizedNode { region : constraint . target , point : constraint . to } ; edges . entry (source) . or_default () . insert (target) ; } let mut logical_edges : FxHashMap < _ , FxIndexSet < _ > > = FxHashMap :: default () ; for constraint in logical_constraints { logical_edges . entry (constraint . sup) . or_default () . insert (constraint . sub) ; } LocalizedConstraintGraph { edges , logical_edges } } #[doc = " Returns the outgoing edges of a given node, not its transitive closure."] fn outgoing_edges (& self , node : LocalizedNode) -> impl Iterator < Item = LocalizedNode > { let physical_edges = self . edges . get (& node) . into_iter () . flat_map (| targets | targets . iter () . copied ()) ; let materialized_edges = self . logical_edges . get (& node . region) . into_iter () . flat_map (move | targets | { targets . iter () . copied () . map (move | target | LocalizedNode { point : node . point , region : target }) }) ; physical_edges . chain (materialized_edges) } }